                    and grid[r][c - 1] == 7 and grid[r][c + 1] == 7
                    and grid[r + 1][c] == 7):
                chevrons.append((r, c))
    aligned = {}
    for r, c in chevrons:
        aligned.setdefault(r, []).append(c)
    special = None
    for r, cols in aligned.items():
        cols.sort()
        if len(cols) == 4 and any(b - a == 1 for a, b in zip(cols, cols[1:])):
            special = (r, cols[1])
    for r, c in chevrons:
        if r >= 5:
            out[r - 5][c] = 1 if (r, c) == special else 9

    # Horizontal rows of arch shapes project diagonally upward and left.
    arches = []
    for r in range(h - 1):
        for c in range(w - 1):
            if (grid[r][c] == color and grid[r][c + 1] == color
                    and grid[r + 1][c] == color and grid[r + 1][c + 1] == 7):
                arches.append((r, c))
    groups = {}
    for r, c in arches:
        groups.setdefault(r, []).append(c)
    valid = []
    for r, cols in groups.items():
        cols.sort()
        if len(cols) >= 2:
            valid.append((r, cols))
            for c in cols:
