def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marks = []

    def val(r, c):
        return grid[r][c] if 0 <= r < h and 0 <= c < w else 7

    # Three-cell chevrons point in the direction in which they emit a marker.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7:
                continue
            if val(r + 1, c - 1) != 7 and val(r + 1, c + 1) != 7:
                marks.append((r - 5, c))       # upward chevron
            if val(r - 1, c - 1) != 7 and val(r - 1, c + 1) != 7:
                marks.append((r + 5, c))       # downward chevron
            if val(r - 1, c + 1) != 7 and val(r + 1, c + 1) != 7:
                marks.append((r, c - 5))       # left-pointing chevron
            if val(r - 1, c - 1) != 7 and val(r + 1, c - 1) != 7:
                marks.append((r, c + 5))       # right-pointing chevron

    # Rows of identical corner shapes emit diagonally up and left.
    corners = {}
    for r in range(h - 1):
        for c in range(w - 1):
            if (grid[r][c] != 7 and grid[r][c + 1] != 7
                    and grid[r + 1][c] != 7 and grid[r + 1][c + 1] == 7):
                corners.setdefault(r, []).append(c)
    for r, cols in corners.items():
        if len(cols) >= 2:
            for c in cols:
                marks.append((r - 5, c - 5))

    for r, c in marks:
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 9

    # The central member of a horizontal sequence of three or four matching
    # objects is highlighted in the source pattern.
    for r, cols in corners.items():
        if len(cols) in (3, 4):
            cols.sort()
            c = cols[len(cols) // 2] if len(cols) == 3 else cols[1]
            out[r][c] = out[r][c + 1] = out[r + 1][c] = 9

    return out
